/**
 * Minimal Source Map v3 reader (no dependency): decode `mappings`, look up an original position for a generated
 * one, and measure how many generated bytes each original source contributes (bundle composition).
 */

export interface RawSourceMap {
  version: number;
  sources: string[];
  sourcesContent?: Array<string | null>;
  names?: string[];
  mappings: string;
  sourceRoot?: string;
  sections?: unknown[];
}

/** One decoded segment: generated column → original source/line/column (+ name). All 0-based. */
interface Segment {
  col: number;
  src?: number;
  line?: number;
  ocol?: number;
  name?: number;
}

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const B64_VAL = new Map([...B64].map((c, i) => [c, i]));

function decodeVlq(s: string, i: number, out: number[]): number {
  out.length = 0;
  let value = 0;
  let shift = 0;
  for (; i < s.length; i++) {
    const c = s[i]!;
    if (c === ',' || c === ';') break;
    const digit = B64_VAL.get(c);
    if (digit === undefined) throw new Error(`Invalid VLQ character "${c}"`);
    value += (digit & 31) << shift;
    if (digit & 32) shift += 5;
    else {
      out.push(value & 1 ? -(value >>> 1) : value >>> 1);
      value = 0;
      shift = 0;
    }
  }
  return i;
}

/** Generated line (0-based) → segments sorted by column. */
export function decodeMappings(mappings: string): Segment[][] {
  const lines: Segment[][] = [[]];
  const fields: number[] = [];
  let src = 0;
  let line = 0;
  let ocol = 0;
  let name = 0;
  let col = 0;
  for (let i = 0; i < mappings.length;) {
    const c = mappings[i]!;
    if (c === ';') {
      lines.push([]);
      col = 0;
      i++;
      continue;
    }
    if (c === ',') {
      i++;
      continue;
    }
    i = decodeVlq(mappings, i, fields);
    col += fields[0] ?? 0;
    const seg: Segment = { col };
    if (fields.length >= 4) {
      src += fields[1]!;
      line += fields[2]!;
      ocol += fields[3]!;
      Object.assign(seg, { src, line, ocol });
      if (fields.length >= 5) seg.name = name += fields[4]!;
    }
    lines.at(-1)!.push(seg);
  }
  return lines;
}

/** 0-based character offset in the generated file → 0-based line/column. */
export function offsetToLineCol(code: string, offset: number) {
  let line = 0;
  let lineStart = 0;
  for (let i = 0; i < Math.min(offset, code.length); i++)
    if (code.charCodeAt(i) === 10) {
      line++;
      lineStart = i + 1;
    }
  return { line, col: offset - lineStart };
}

/** Webpack/Vite/Rollup source paths → readable project paths. */
export function cleanSource(source: string, sourceRoot = ''): string {
  return (sourceRoot && !/^[a-z]+:/.test(source) ? sourceRoot.replace(/\/?$/, '/') + source : source)
    .replace(/^(webpack|turbopack|vite|rollup):\/{2,3}(\[project\]\/|_N_E\/|[^/]*\/)?/i, '')
    .replace(/^(\.\.?\/)+/, '')
    .replace(/\?[^/]*$/, '');
}

export function packageOf(source: string): string | undefined {
  const m = source.match(/node_modules\/((?:@[^/]+\/)?[^/]+)/);
  return m?.[1];
}

export class SourceMapReader {
  private readonly lines: Segment[][];

  constructor(private readonly map: RawSourceMap) {
    if (map.sections) throw new Error('Indexed source maps (sections) are not supported');
    this.lines = decodeMappings(map.mappings);
  }

  get sourceCount() {
    return this.map.sources.length;
  }

  source(i: number) {
    return cleanSource(this.map.sources[i] ?? '', this.map.sourceRoot);
  }

  /** Original position for a 0-based generated line/column (nearest segment at or before the column). */
  originalPosition(line: number, col: number) {
    const segs = this.lines[line];
    if (!segs?.length) return undefined;
    let best: Segment | undefined;
    for (const s of segs) {
      if (s.col > col) break;
      if (s.src !== undefined) best = s;
    }
    if (!best || best.src === undefined) return undefined;
    return {
      source: this.source(best.src),
      line: best.line! + 1,
      column: best.ocol!,
      name: best.name !== undefined ? this.map.names?.[best.name] : undefined,
      content: this.map.sourcesContent?.[best.src] ?? undefined,
    };
  }

  /** Generated bytes attributed to each original source (requires the generated code for line lengths). */
  composition(code: string) {
    const lineLengths = code.split('\n').map((l) => l.length);
    const bytes = new Map<number, number>();
    this.lines.forEach((segs, li) => {
      for (let k = 0; k < segs.length; k++) {
        const s = segs[k]!;
        if (s.src === undefined) continue;
        const end = segs[k + 1]?.col ?? lineLengths[li] ?? s.col;
        bytes.set(s.src, (bytes.get(s.src) ?? 0) + Math.max(0, end - s.col));
      }
    });
    return [...bytes.entries()].map(([src, n]) => ({ source: this.source(src), bytes: n }));
  }
}
